test("a human running git directly is never locked out", () => {
  const verdict = ownershipVerdict({ recorded: "", session: "" });
  assert.deepEqual(verdict, { action: "skip", reason: "no session identity" });
});

test("the primary checkout is exempt, whatever is recorded", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:someone",
    session: "session:v1:me",
    linked: false,
  });
  assert.deepEqual(verdict, { action: "skip", reason: "primary checkout" });
});

test("a deliberate adopt always records, even over an existing owner", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:someone",
    session: "session:v1:me",
    adopt: true,
  });
  assert.deepEqual(verdict, {
    action: "record",
    reason: "deliberate handover",
  });
});

test("an unclaimed linked worktree is claimed by the acting session", () => {
  const verdict = ownershipVerdict({
    recorded: "",
    session: "session:v1:me",
  });
  assert.deepEqual(verdict, {
    action: "record",
    reason: "first commit claims the worktree",
  });
});

test("the recorded owner may keep acting in its own worktree", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:me",
    session: "session:v1:me",
  });
  assert.deepEqual(verdict, { action: "allow", reason: "owner" });
});

test("a different session is refused, and the owner is named", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:someone",
    session: "session:v1:me",
  });
  assert.deepEqual(verdict, {
    action: "refuse",
    reason: "owned by another agent",
    owner: "session:v1:someone",
  });
});

test("the refusal message names both the owner and the acting session", () => {
  const message = refusalMessage({
    owner: "session:v1:someone",
    session: "session:v1:me",
  });
  assert.match(message, /worktree owner : session:v1:someone/);
  assert.match(message, /you\s+: session:v1:me/);
  assert.match(message, /--adopt-worktree/);
});

// The regression this gap fix exists for: a linked worktree that has been
// created and declared, but never committed in, previously had no marker at
// all, so any guard consulting one read it as unclaimed. `git worktree add`
// fires `post-checkout` the moment it completes (confirmed empirically), and
// the hook now runs `worktree-owner.mjs --stage=post-checkout` there. This
// drives that exact script, through a real git worktree, with no commit ever
// made, and asserts the marker already names the creating session.
const run = (args, cwd) => execFileSync("git", args, { cwd, encoding: "utf8" });
const scriptPath = fileURLToPath(
  new URL("./worktree-owner.mjs", import.meta.url),
);

test("a freshly created worktree is owned before any commit is made", () => {
  const root = mkdtempSync(join(tmpdir(), "worktree-owner-"));
  const session = "session:v1:creating-agent";
  try {
    run(["init", "-q", "-b", "main"], root);
    run(["config", "user.email", "probe@example.com"], root);
    run(["config", "user.name", "Probe"], root);
    run(["commit", "-q", "--allow-empty", "-m", "init"], root);

    const wtPath = join(root, "wt1");
    run(["worktree", "add", "-b", "feature/x", wtPath, "main"], root);

    // Simulate the post-checkout hook firing right after creation, before the
    // creating session has committed anything in the new worktree.
    execFileSync("node", [scriptPath, "--stage=post-checkout"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: session },
    });

    const gitDir = run(["rev-parse", "--absolute-git-dir"], wtPath).trim();
    const markerPath = join(gitDir, MARKER_NAME);
    assert.equal(
      existsSync(markerPath),
      true,
      "the marker must exist before any commit",
    );
    assert.equal(readFileSync(markerPath, "utf8").trim(), session);

    // No commit exists in the new worktree yet — the marker predates it.
    const log = run(
      ["log", "--oneline", "feature/x", "--not", "main"],
      wtPath,
    ).trim();
    assert.equal(log, "", "the branch must carry no commits of its own yet");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("post-checkout warns rather than refusing when another session owns it", () => {
  const root = mkdtempSync(join(tmpdir(), "worktree-owner-"));
  try {
    run(["init", "-q", "-b", "main"], root);
    run(["config", "user.email", "probe@example.com"], root);
    run(["config", "user.name", "Probe"], root);
    run(["commit", "-q", "--allow-empty", "-m", "init"], root);

    const wtPath = join(root, "wt1");
    run(["worktree", "add", "-b", "feature/x", wtPath, "main"], root);
    execFileSync("node", [scriptPath, "--stage=post-checkout"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: "session:v1:owner" },
    });

    // A different session's post-checkout must not throw or block: git has
    // already performed the checkout, so this can only ever warn.
    const result = spawnSync("node", [scriptPath, "--stage=post-checkout"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: "session:v1:intruder" },
    });
    assert.equal(result.status, 0, "post-checkout must never block a checkout");
    assert.match(
      result.stderr,
      /this worktree already belongs to another agent/,
    );
    assert.match(result.stderr, /session:v1:owner/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

// The regression this fix exists for: `view=next`/`view=overlap` and local git
// state can both read clean while the original owner already pushed and
// opened a PR seconds before their lease lapsed, so a rescue can cherry-pick
// an already-shipped commit onto a fresh branch and republish it as a second,
// duplicate PR (gaps.d/rescuing-a-lapsed-lease-can-duplicate-a-published-pr.md).
// `capture` is injected so these never spawn a real `gh` process.

test("an existing pull request is reported through the injected gh call", () => {
  const calls = [];
  const result = checkExistingPullRequests({
    branch: "feat/example",
    capture: (args, cwd) => {
      calls.push({ args, cwd });
      return JSON.stringify([
        { number: 414, state: "OPEN", url: "https://example/pulls/414" },
      ]);
    },
  });
  assert.deepEqual(result, {
    checked: true,
    pullRequests: [
      { number: 414, state: "OPEN", url: "https://example/pulls/414" },
    ],
  });
  assert.deepEqual(calls[0].args, [
    "pr",
    "list",
    "--head",
    "feat/example",
    "--state",
    "all",
    "--json",
    "number,state,url",
  ]);
});

test("no pull requests reports an empty, checked result", () => {
  const result = checkExistingPullRequests({
    branch: "feat/example",
    capture: () => "[]",
  });
  assert.deepEqual(result, { checked: true, pullRequests: [] });
});

test("gh being unavailable or unauthenticated degrades to unchecked, not a throw", () => {
  const result = checkExistingPullRequests({
    branch: "feat/example",
    capture: () => {
      throw new Error("gh: command not found");
    },
  });
  assert.deepEqual(result, { checked: false, pullRequests: [] });
});

test("malformed gh output degrades to unchecked rather than crashing", () => {
  const result = checkExistingPullRequests({
    branch: "feat/example",
    capture: () => "not json",
  });
  assert.deepEqual(result, { checked: false, pullRequests: [] });
});

test("no warning is raised when the branch has no pull request", () => {
  const warning = existingPullRequestWarning({
    branch: "feat/example",
    checked: true,
    pullRequests: [],
  });
  assert.equal(warning, null);
});

test("an existing pull request is named in the warning, not just counted", () => {
  const warning = existingPullRequestWarning({
    branch: "feat/example",
    checked: true,
    pullRequests: [
      { number: 414, state: "OPEN", url: "https://example/pulls/414" },
    ],
  });
  assert.match(warning, /feat\/example/);
  assert.match(warning, /#414 \(OPEN\) https:\/\/example\/pulls\/414/);
  assert.match(warning, /rescuing-a-lapsed-lease-can-duplicate-a-published-pr/);
});

test("an unchecked result still warns, naming the fallback command", () => {
  const warning = existingPullRequestWarning({
    branch: "feat/example",
    checked: false,
    pullRequests: [],
  });
  assert.match(warning, /could not check GitHub/);
  assert.match(warning, /gh pr list --head feat\/example --state all/);
});

// The regression this fix exists for
// (gaps.d/adopt-worktree-takes-a-peers-uncommitted-work.md): the adopt path's
// only pre-flight was a *remote* lookup, so it never noticed that the
// worktree being taken over held a peer's uncommitted work. `capture` is
// injected so these never spawn a real `git` process.

test("a dirty tree is parsed into bare paths, stripping the porcelain status codes", () => {
  const result = checkWorkingTreeDirty({
    capture: () =>
      " M crates/ackplane-server/src/lib.rs\n" +
      "?? migrations/0038_work_task_command_execution.sql\n",
  });
  assert.deepEqual(result, {
    checked: true,
    paths: [
      "crates/ackplane-server/src/lib.rs",
      "migrations/0038_work_task_command_execution.sql",
    ],
  });
});

test("a clean tree reports checked with no paths", () => {
  const result = checkWorkingTreeDirty({ capture: () => "" });
  assert.deepEqual(result, { checked: true, paths: [] });
});

test("git failing to report status degrades to unchecked, not a throw", () => {
  const result = checkWorkingTreeDirty({
    capture: () => {
      throw new Error("not a git repository");
    },
  });
  assert.deepEqual(result, { checked: false, paths: [] });
});

test("no warning is raised when the tree is clean", () => {
  const warning = dirtyWorkingTreeWarning({ checked: true, paths: [] });
  assert.equal(warning, null);
});

test("a dirty tree names the affected paths and the gap that motivates the check", () => {
  const warning = dirtyWorkingTreeWarning({
    checked: true,
    paths: [
      "crates/ackplane-server/src/lib.rs",
      "migrations/0038_work_task_command_execution.sql",
    ],
  });
  assert.match(warning, /crates\/ackplane-server\/src\/lib\.rs/);
  assert.match(warning, /migrations\/0038_work_task_command_execution\.sql/);
  assert.match(warning, /adopt-worktree-takes-a-peers-uncommitted-work/);
});

test("a long dirty file list is truncated rather than dumped in full", () => {
  const paths = Array.from({ length: 15 }, (_, i) => `file${i}.txt`);
  const warning = dirtyWorkingTreeWarning({ checked: true, paths });
  assert.match(warning, /file0\.txt/);
  assert.match(warning, /\(\+5 more\)/);
  assert.doesNotMatch(warning, /file14\.txt/);
});

test("an unchecked dirty-tree result still warns, naming the fallback command", () => {
  const warning = dirtyWorkingTreeWarning({ checked: false, paths: [] });
  assert.match(warning, /could not check whether this worktree/);
  assert.match(warning, /git status/);
});

// End-to-end: adopting a worktree that holds a peer's uncommitted work must
// print a loud warning naming the affected files, not silently record the
// handover. This is the exact incident shape: a worktree with real,
// unstaged/untracked changes, adopted by a different session.
test("adopting a worktree with uncommitted changes warns and names the files", () => {
  const root = mkdtempSync(join(tmpdir(), "worktree-owner-"));
  try {
    run(["init", "-q", "-b", "main"], root);
    run(["config", "user.email", "probe@example.com"], root);
    run(["config", "user.name", "Probe"], root);
    run(["config", "advice.detachedHead", "false"], root);
    writeFileSync(join(root, "tracked.txt"), "original\n");
    run(["add", "tracked.txt"], root);
    run(["commit", "-q", "-m", "init"], root);

    const wtPath = join(root, "wt1");
    run(["worktree", "add", "-b", "feature/x", wtPath, "main"], root);

    // The peer's live, uncommitted work: an edit to a tracked file and a new
    // untracked file, mirroring the incident's modified sources plus its
    // untracked migration.
    writeFileSync(join(wtPath, "tracked.txt"), "peer's in-progress edit\n");
    writeFileSync(join(wtPath, "untracked.sql"), "-- peer's new migration\n");

    const result = spawnSync("node", [scriptPath, "--adopt-worktree"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: "session:v1:adopter" },
    });
    assert.match(result.stderr, /uncommitted changes/);
    assert.match(result.stderr, /tracked\.txt/);
    assert.match(result.stderr, /untracked\.sql/);
    assert.match(
      result.stderr,
      /adopt-worktree-takes-a-peers-uncommitted-work/,
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
